// Syncs the tokenizer artifacts (fixed UCI vocabulary, trained BPE model and the Python parity
// fixture) into src/lib/chess-lm/, and generates the `squares` parity fixture from the Python
// module itself. By default the artifacts are copied from the ML repo checked out next to this
// one; `--from <baseUrl>` downloads them instead (e.g. from the Hugging Face Hub).
//
// The squares fixture is never downloaded: it is not an exported artifact but the answer of
// `rukh/src/rukh/models/squares.py` to the positions below, so it is regenerated by running that
// module in the ML repo's own virtualenv (read-only: `uv run --no-sync`, and no bytecode is
// written) and re-verified against the TypeScript twin before it is written. `--no-squares`
// skips that step on a machine with no ../rukh checkout.
// Usage: pnpm sync:tokenizer [--from <baseUrl-or-dir>] [--no-squares]
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { format, resolveConfig } from 'prettier';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const localSource = '../rukh/artifacts/tokenizer';
const HUB_SOURCE = 'https://huggingface.co/chorcat/rukh-tokenizer/resolve/main';
const files = ['vocab.json', 'bpe.json', 'fixtures/games.json'];

const VOCAB_SIZE = 2030;
const FIXTURE_GAMES = 20;
const FIXTURE_KEYS = [
  'id',
  'uci',
  'san',
  'white_elo',
  'black_elo',
  'result',
  'uci_ids',
  'san_ids',
  'bpe_ids',
];

/**
 * Rejects a file that parses as JSON but is not the artifact we expect, so a half-written or
 * stale export fails here instead of silently landing in src/lib/chess-lm/.
 */
function validate(name, data) {
  const fail = (why) => {
    throw new Error(`${name}: ${why}`);
  };
  if (name === 'vocab.json') {
    if (!Array.isArray(data?.tokens)) fail('no `tokens` array');
    if (data.tokens.length !== VOCAB_SIZE) {
      fail(`tokens.length is ${data.tokens.length}, expected ${VOCAB_SIZE}`);
    }
    if (!data.tokens.every((token) => typeof token === 'string')) fail('tokens are not strings');
  }
  if (name === 'bpe.json') {
    const model = data?.model;
    if (!model) fail('no `model` object');
    if (!model.vocab || typeof model.vocab !== 'object') fail('no `model.vocab` object');
    if (!Array.isArray(model.merges) || model.merges.length === 0) fail('no `model.merges` list');
  }
  if (name === 'fixtures/games.json') {
    const games = Array.isArray(data) ? data : data?.games;
    if (!Array.isArray(games)) fail('not an array of games');
    if (games.length !== FIXTURE_GAMES) {
      fail(`${games.length} games, expected ${FIXTURE_GAMES}`);
    }
    games.forEach((game, i) => {
      const missing = FIXTURE_KEYS.filter((key) => game?.[key] === undefined);
      if (missing.length > 0) fail(`game ${i} is missing ${missing.join(', ')}`);
    });
  }
}

// ------------------------------------------------------------------
// The squares fixture: generated from Python, verified against TypeScript
// ------------------------------------------------------------------

const PYTHON_MODULE = 'rukh/src/rukh/models/squares.py';
const SQUARES_FIXTURE = 'src/lib/chess-lm/fixtures/squares.json';
const SQUARES_TWIN = '../src/lib/chess-lm/squares.ts';
const PY_PROJECT = '../rukh';

/**
 * The positions the two implementations are compared on. They are the fixture's contract, so they
 * live here and not in the generated file: every branch of the scheme has to be walked by at
 * least one of them, or a drift between Python and TypeScript could hide in the gap.
 */
const SQUARES_CASES = [
  // An opening move by move, and the four-field form the P1 positions are keyed by.
  'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1',
  'rnbqkbnr/pppppppp/8/8/4P3/8/PPPP1PPP/RNBQKBNR b KQkq e3 0 1',
  'rnbqkbnr/pp1ppppp/8/2p5/4P3/8/PPPP1PPP/RNBQKBNR w KQkq c6 0 2',
  'rnbqkbnr/pp1ppppp/8/2p5/4P3/5N2/PPPP1PPP/RNBQKB1R b KQkq - 1 2',
  'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq -',
  'r1bqkbnr/pppp1ppp/2n5/4p3/2B1P3/5N2/PPPP1PPP/RNBQK2R b KQkq -',
  // Every castling combination, including one written out of order.
  'r3k2r/pppppppp/8/8/8/8/PPPPPPPP/R3K2R w KQkq - 0 1',
  'r3k2r/pppppppp/8/8/8/8/PPPPPPPP/R3K2R w K - 0 1',
  'r3k2r/pppppppp/8/8/8/8/PPPPPPPP/R3K2R w Q - 0 1',
  'r3k2r/pppppppp/8/8/8/8/PPPPPPPP/R3K2R b k - 0 1',
  'r3k2r/pppppppp/8/8/8/8/PPPPPPPP/R3K2R b q - 0 1',
  'r3k2r/pppppppp/8/8/8/8/PPPPPPPP/R3K2R w KQ - 0 1',
  'r3k2r/pppppppp/8/8/8/8/PPPPPPPP/R3K2R b kq - 0 1',
  'r3k2r/pppppppp/8/8/8/8/PPPPPPPP/R3K2R w Kq - 0 1',
  'r3k2r/pppppppp/8/8/8/8/PPPPPPPP/R3K2R b Qk - 0 1',
  'r3k2r/pppppppp/8/8/8/8/PPPPPPPP/R3K2R w Qkq - 0 1',
  'r3k2r/pppppppp/8/8/8/8/PPPPPPPP/R3K2R w Kkq - 0 1',
  'r3k2r/pppppppp/8/8/8/8/PPPPPPPP/R3K2R w KQq - 0 1',
  'r3k2r/pppppppp/8/8/8/8/PPPPPPPP/R3K2R w KQk - 0 1',
  'r3k2r/pppppppp/8/8/8/8/PPPPPPPP/R3K2R w - - 0 1',
  'r3k2r/pppppppp/8/8/8/8/PPPPPPPP/R3K2R w qkQK - 0 1',
  // En passant on both colours and on the edge files: the rank is dropped, the file is not.
  'rnbqkbnr/ppp1pppp/8/3pP3/8/8/PPPP1PPP/RNBQKBNR w KQkq d6 0 3',
  'rnbqkbnr/pppp1ppp/8/8/4pP2/8/PPPPP1PP/RNBQKBNR b KQkq f3 0 3',
  '8/8/8/pP6/8/8/8/K6k w - a6 0 30',
  '8/8/8/8/1pP5/8/8/K6k b - c3 0 30',
  '8/8/8/6Pp/8/8/8/K6k w - h6 0 30',
  '8/8/8/8/6pP/8/8/K6k b - g3 0 30',
  // Promotions: the pieces that only ever appear at the end of a game.
  '8/P6k/8/8/8/8/7K/8 w - - 0 60',
  'Q6k/8/8/8/8/8/7K/8 b - - 0 61',
  '8/7K/8/8/8/8/p6k/8 b - - 0 60',
  '8/7K/8/8/8/8/7k/q7 w - - 0 61',
  // Endgames with a piece nearly alone on the board.
  '8/8/8/8/8/5k2/6n1/5K1N w - - 3 80',
  '8/8/4k3/8/8/4K3/4P3/8 w - - 0 45',
  '8/5k2/8/8/8/8/3R4/4K3 b - - 12 55',
  '8/8/8/3k4/8/3K4/8/7R w - - 99 120',
  // The same position at every halfmove-clock boundary: 5, 6, 24, 25, 49, 50 and 137.
  'r1bqkb1r/pppp1ppp/2n2n2/4p3/2B1P3/5N2/PPPP1PPP/RNBQK2R w KQkq - 5 5',
  'r1bqkb1r/pppp1ppp/2n2n2/4p3/2B1P3/5N2/PPPP1PPP/RNBQK2R w KQkq - 6 5',
  'r1bqkb1r/pppp1ppp/2n2n2/4p3/2B1P3/5N2/PPPP1PPP/RNBQK2R w KQkq - 24 15',
  'r1bqkb1r/pppp1ppp/2n2n2/4p3/2B1P3/5N2/PPPP1PPP/RNBQK2R w KQkq - 25 20',
  'r1bqkb1r/pppp1ppp/2n2n2/4p3/2B1P3/5N2/PPPP1PPP/RNBQK2R w KQkq - 49 40',
  'r1bqkb1r/pppp1ppp/2n2n2/4p3/2B1P3/5N2/PPPP1PPP/RNBQK2R w KQkq - 50 60',
  'r1bqkb1r/pppp1ppp/2n2n2/4p3/2B1P3/5N2/PPPP1PPP/RNBQK2R w KQkq - 137 180',
  // A middlegame with no rights left, and the emptiest legal board there is.
  'r2q1rk1/pp2ppbp/2np1np1/2p5/2P1P3/2NP1N2/PP2BPPP/R1BQ1RK1 b - - 4 9',
  '8/8/8/8/8/8/8/K6k w - - 0 1',
];

/** What the Python module is asked to answer, with the positions fed in on stdin. */
const PY_SOURCE = `
import json, sys
from rukh.models.squares import SQUARE_TOKENS, SQUARE_VOCAB, fen_to_tokens, vocab_hash
fens = json.load(sys.stdin)
json.dump({
    "source": "${PYTHON_MODULE}",
    "tokens": SQUARE_TOKENS,
    "vocab": SQUARE_VOCAB,
    "vocab_hash": vocab_hash(),
    "cases": [{"fen": fen, "ids": fen_to_tokens(fen)} for fen in fens],
}, sys.stdout)
`;

/** Runs the module in ../rukh's virtualenv and returns what it answered, or explains why not. */
function askPython(fens) {
  const result = spawnSync(
    'uv',
    // `--no-sync`: never resolve, install or touch anything under ../rukh.
    ['run', '--project', PY_PROJECT, '--no-sync', 'python', '-c', PY_SOURCE],
    {
      cwd: root,
      input: JSON.stringify(fens),
      encoding: 'utf8',
      // No .pyc anywhere either: the ML repo is somebody else's working tree and a sync must not
      // write a single byte into it.
      env: { ...process.env, PYTHONDONTWRITEBYTECODE: '1' },
      // No `shell`: the program below is multi-line and a shell would mangle it into pieces.
      shell: false,
    },
  );
  if (result.error?.code === 'ENOENT') {
    throw new Error(`uv is not on PATH, so ${PYTHON_MODULE} cannot be run`);
  }
  if (result.error) throw result.error;
  if (result.status !== 0) {
    const why = (result.stderr || '').trim().split('\n').slice(-4).join('\n');
    throw new Error(
      `uv run --project ${PY_PROJECT} failed (exit ${result.status}).\n${why}\n` +
        'Check that ../rukh is checked out and that `uv sync` has been run there.',
    );
  }
  try {
    return JSON.parse(result.stdout);
  } catch {
    throw new Error(`${PYTHON_MODULE} did not answer JSON: ${result.stdout.slice(0, 200)}`);
  }
}

/**
 * Checks what Python answered against the TypeScript twin the browser actually runs — the whole
 * point of the fixture — and against the invariants of the scheme itself. Node imports the .ts
 * file directly (type stripping), so this is the very module `src/lib/chess-lm/index.ts`
 * re-exports, not a copy of it.
 */
async function verifySquares(payload) {
  const twin = await import(SQUARES_TWIN);
  const fail = (why) => {
    throw new Error(`${SQUARES_FIXTURE}: ${why}`);
  };
  if (payload.tokens !== twin.SQUARE_TOKENS) {
    fail(`Python says ${payload.tokens} tokens and squares.ts says ${twin.SQUARE_TOKENS}`);
  }
  const vocab = twin.buildSquareVocab();
  if (JSON.stringify(payload.vocab) !== JSON.stringify(vocab)) {
    fail('the two vocabularies do not match token for token');
  }
  const hash = createHash('sha256').update(JSON.stringify(vocab), 'ascii').digest('hex');
  if (hash !== payload.vocab_hash) {
    fail(`vocab_hash is ${payload.vocab_hash} and the vocabulary hashes to ${hash}`);
  }
  if (payload.cases.length !== SQUARES_CASES.length) {
    fail(`${payload.cases.length} positions, expected ${SQUARES_CASES.length}`);
  }
  for (const [index, entry] of payload.cases.entries()) {
    const mine = twin.fenToTokens(entry.fen);
    if (mine.length !== payload.tokens) fail(`position ${index} has ${mine.length} ids`);
    if (JSON.stringify(mine) !== JSON.stringify(entry.ids)) {
      fail(`position ${index} (${entry.fen}) differs: Python ${entry.ids}, squares.ts ${mine}`);
    }
    if (!entry.ids.every((id) => Number.isInteger(id) && id >= 0 && id < vocab.length)) {
      fail(`position ${index} (${entry.fen}) has an id outside the vocabulary`);
    }
  }
}

/** Regenerates `fixtures/squares.json` from the Python module, verified before it is written. */
async function syncSquares() {
  const payload = askPython(SQUARES_CASES);
  await verifySquares(payload);
  const target = resolve(root, SQUARES_FIXTURE);
  mkdirSync(dirname(target), { recursive: true });
  // Written the way `pnpm format` would write it, so a sync never leaves `format:check` red.
  const options = await resolveConfig(target);
  writeFileSync(target, await format(JSON.stringify(payload), { ...options, filepath: target }));
  console.log(
    `generated fixtures/squares.json from ${PYTHON_MODULE} ` +
      `(${payload.cases.length} positions, vocab_hash ${payload.vocab_hash.slice(0, 12)})`,
  );
}

const args = process.argv.slice(2);
const fromIndex = args.indexOf('--from');
let source = localSource;
if (fromIndex >= 0) {
  source = args[fromIndex + 1] ?? HUB_SOURCE;
  if (source.startsWith('--')) source = HUB_SOURCE;
}
const isUrl = /^https?:\/\//.test(source);

async function read(name) {
  if (isUrl) {
    const url = `${source.replace(/\/$/, '')}/${name}`;
    const response = await fetch(url);
    if (!response.ok) throw new Error(`${url}: HTTP ${response.status}`);
    return response.text();
  }
  const path = resolve(root, source, name);
  if (!existsSync(path)) throw new Error(`${path}: file not found`);
  return readFileSync(path, 'utf8');
}

const skipSquares = args.includes('--no-squares');

try {
  for (const name of files) {
    const text = await read(name);
    validate(name, JSON.parse(text)); // fail early on a truncated download or a stale export
    const target = resolve(root, 'src/lib/chess-lm', name);
    mkdirSync(dirname(target), { recursive: true });
    writeFileSync(target, text.endsWith('\n') ? text : `${text}\n`);
    console.log(`synced ${name} (${text.length} bytes)`);
  }
  console.log(`tokenizer synced from ${source}`);
  if (skipSquares) {
    console.log('fixtures/squares.json left untouched (--no-squares)');
  } else {
    await syncSquares();
  }
} catch (error) {
  console.error(`sync:tokenizer failed: ${error instanceof Error ? error.message : error}`);
  console.error(
    `Expected ${files.join(', ')} under ${source}. Run \`rukh data tokenize --export-fixture\` ` +
      `in ../rukh first, or pass --from ${HUB_SOURCE}. The squares fixture is generated and ` +
      `never downloaded: it needs the ../rukh checkout and its virtualenv, or --no-squares.`,
  );
  process.exit(1);
}
